using Microsoft.EntityFrameworkCore;
class BlogContext : DbContext
{
    public DbSet<Blog> Blogs => Set<Blog>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Blog>(entity =>
        {
            // Breaking change 1: EF 9 renamed "Discriminator" → "$type".
            // Existing documents use "Discriminator", so preserve it.
            entity.HasDiscriminator().HasJsonPropertyName("Discriminator");

            // Breaking change 2: EF 9 changed id format from "EntityType|Key" → Key only.
            // Existing documents use "Blog|<key>", so restore the old format.
            entity.HasPartitionKey(b => b.Id);
            entity.Property(b => b.Id)
                  .ToJsonProperty("id")
                  .HasValueGenerator<LegacyIdValueGenerator>();

            // Breaking change 3: EF 9 removed Cosmos DB indexing support via HasIndex().
            // HasIndex() on Cosmos now throws; remove it. Manage indexes via Azure portal/IaC.
        });
    }
}

class Blog
{
    public string Id { get; set; }
    public string Name { get; set; }
}

